SELECT s.interval_code, s.original_decision, s.decision, s.confluence_status, s.confluence_higher_decision, COUNT(*) AS n, MIN(s.generated_at) AS first_at, MAX(s.generated_at) AS last_at FROM trade_signal s WHERE s.generated_at >= '2026-10-11 00:00:00' AND s.generated_at < '2026-10-16 00:00:00' AND s.interval_code IN ('5m','1h') AND s.original_decision IN ('SELL','STRONG_SELL') GROUP BY s.interval_code, s.original_decision, s.decision, s.confluence_status, s.confluence_higher_decision ORDER BY n DESC LIMIT 50